#!/usr/bin/bash

echo "::group:: ===$(basename "$0")==="

set -eoux pipefail

# Rebrand the Bluefin-specific files shipped by projectbluefin/common as Amethystora.
# The artwork itself lives in system_files/shared and is generated by branding/generate.mjs.

REPO="iarsslen/amethystora"
REPO_URL="https://github.com/${REPO}"

# Wallpapers: remove the Bluefin set and its monthly rotation, Amethystora's are set in zz1-amethystora-modifications
rm -rf /usr/share/backgrounds/bluefin
{ grep -l "/usr/share/backgrounds/bluefin" /usr/share/gnome-background-properties/*.xml || true; } | xargs -r rm -f
rm -f /usr/lib/systemd/user/bluefin-dynamic-wallpaper.{service,timer} \
    /usr/libexec/bluefin-dynamic-wallpaper \
    /usr/share/ublue-os/user-setup.hooks.d/20-dynamic-wallpaper.sh

# Only the Amethystora logo is used by fastfetch (see /etc/amethystora/fastfetch.json)
rm -rf /usr/share/ublue-os/bluefin-logos

# The files below come from the pinned projectbluefin/common image and change between its releases.
# Skip, with a warning, any that the pinned version does not ship instead of failing the build.
upstream_has() {
    local file
    for file in "$@"; do
        if [[ ! -f "${file}" ]]; then
            echo "::warning::${file} not found, skipping its Amethystora branding"
            return 1
        fi
    done
}

# fastfetch: drop the Bluefin user count and use the Amethystora palette
FASTFETCH_CONFIG=/usr/share/ublue-os/fastfetch.jsonc
if upstream_has "${FASTFETCH_CONFIG}"; then
    jq 'del(.modules[] | select(type == "object" and ((.format // "") | contains("Murder Chickens"))))' \
        "${FASTFETCH_CONFIG}" >/tmp/fastfetch.jsonc
    sed -e 's/38;2;87;160;198/38;2;124;58;237/g' -e 's/#57a0c6/#7c3aed/g' /tmp/fastfetch.jsonc >"${FASTFETCH_CONFIG}"
    rm -f /tmp/fastfetch.jsonc
fi
rm -f /usr/share/ublue-os/fastfetch-user-count

# Boot menu: GRUB reads its own bitmap font format, so the Inter that theme.txt asks for is built
# here from the TTF the image already ships for the boot splash. GRUB looks the font up by the name
# stored in the file, which grub2-mkfont always writes as "<family> <style> <size>" — for a regular
# face, "<family> Regular 16". The family is given here instead of being taken from the TTF, whose
# own family name is "Inter 18pt" in some Inter releases and would stop matching theme.txt.
GRUB_THEME_DIR=/usr/share/grub/themes/amethystora
GRUB_FONT_NAME="Inter Regular 16"
grub2-mkfont --size=16 --name="Inter" \
    --output="${GRUB_THEME_DIR}/font16.pf2" /usr/share/fonts/rsms-inter-fonts/Inter-Regular.ttf
test -s "${GRUB_THEME_DIR}/font16.pf2"
# The name in the font file and the name theme.txt asks for have to be the same string, or the menu
# silently falls back to GRUB's own font
grep -aq "${GRUB_FONT_NAME}" "${GRUB_THEME_DIR}/font16.pf2"
grep -qE "^[[:space:]]*item_font = \"${GRUB_FONT_NAME}\"$" "${GRUB_THEME_DIR}/theme.txt"

# Boot splash: the Amethystora theme runs on the script plugin (amethystora.script and its images, from
# branding/generate.mjs). Its Font= lines are not read by the plugin but make dracut put Inter in the initramfs.
# 19-initramfs.sh bakes the selected theme into the initramfs.
plymouth-set-default-theme amethystora

# Help and community shortcuts. Upstream's Documentation launcher opened a PDF of its own docs, which
# 07-debrand.sh removes; the Amethystora Manual (amethystora-manual.desktop) takes its place.
rm -f /usr/share/applications/documentation.desktop
if upstream_has /usr/share/applications/discourse.desktop; then
    sed -i -e "s|^Exec=.*|Exec=xdg-open ${REPO_URL}/discussions|" -e 's/Bluefin/Amethystora/g' /usr/share/applications/discourse.desktop
fi
for desktop in system-update bluefin-help; do
    if upstream_has "/usr/share/applications/${desktop}.desktop"; then
        sed -i 's/Bluefin/Amethystora/g' "/usr/share/applications/${desktop}.desktop"
    fi
done

# Universal Blue icons: switch the launchers to the Amethystora icons and drop the originals
sed -i \
    -e 's/^Icon=ublue-docs$/Icon=amethystora-docs/' \
    -e 's/^Icon=ublue-discourse$/Icon=amethystora-community/' \
    -e 's/^Icon=ublue-update$/Icon=amethystora-update/' \
    /usr/share/applications/*.desktop
rm -f /usr/share/icons/hicolor/scalable/actions/ublue-logo-symbolic.svg \
    /usr/share/icons/hicolor/scalable/places/ublue-{docs,discourse,update}.svg

# Upstream artwork under Fedora's own file names. projectbluefin/common overwrites Fedora's logo
# files with Bluefin's and Universal Blue's pictures, so the names hold no Bluefin or Universal Blue
# text for 07-debrand.sh to rename while the images are still theirs. The names cannot be renamed
# either: they are where GDM, the Settings About page (gnome-control-center is built with the path
# baked in) and Fedora's fallback boot splash look. The pictures are replaced here instead.
declare -A UPSTREAM_ARTWORK=(
    # The login screen, which draws on a dark background: the wordmark with the dark lettering
    # disappears into it and leaves the gem on its own. The lit variant, matching the stone the boot
    # splash hands over still glowing. zz1-amethystora-modifications names the same file directly as
    # well, so the greeter is right whichever of the two GDM reads.
    [/usr/share/pixmaps/fedora-gdm-logo.png]=/usr/share/pixmaps/amethystora-wordmark-glow.png
    [/usr/share/pixmaps/fedora-logo-small.png]=/usr/share/pixmaps/amethystora-wordmark-small.png
    [/usr/share/pixmaps/fedora-logo.png]=/usr/share/pixmaps/amethystora-wordmark.png
    [/usr/share/pixmaps/fedora_logo_med.png]=/usr/share/pixmaps/amethystora-wordmark-medium.png
    [/usr/share/pixmaps/fedora_whitelogo_med.png]=/usr/share/pixmaps/amethystora-wordmark-white.png
    # Settings -> About draws fedora-logo-icon.png, the path Fedora compiles into gnome-control-center
    [/usr/share/pixmaps/fedora-logo-icon.png]=/usr/share/pixmaps/amethystora-logo-512.png
    [/usr/share/pixmaps/fedora-logo-sprite.png]=/usr/share/pixmaps/amethystora-logo-400.png
    [/usr/share/pixmaps/system-logo-white.png]=/usr/share/pixmaps/amethystora-logo-white.png
    [/usr/share/icons/hicolor/scalable/places/fedora-logo-sprite.svg]=/usr/share/icons/hicolor/scalable/apps/amethystora-logo.svg
    [/usr/share/icons/hicolor/scalable/places/fedora_white_logo.svg]=/usr/share/icons/hicolor/scalable/apps/amethystora-logo.svg
    [/usr/share/icons/hicolor/scalable/places/fedora_whitelogo.svg]=/usr/share/icons/hicolor/scalable/apps/amethystora-logo.svg
    # Fedora's spinner theme is the fallback splash; its watermark.png is an Amethystora file already
    [/usr/share/plymouth/themes/spinner/silverblue-watermark.png]=/usr/share/plymouth/themes/spinner/watermark.png
)

for target in "${!UPSTREAM_ARTWORK[@]}"; do
    artwork="${UPSTREAM_ARTWORK[${target}]}"
    test -s "${artwork}"
    install -Dpm0644 "${artwork}" "${target}"
done

# A logo arriving under a name nothing recognises would ship as it is, so the build stops until it
# is given an Amethystora picture above. Names that still say Bluefin or Universal Blue are left to
# 07-debrand.sh, which renames them, and to 20-tests.sh, which fails on the ones it cannot.
# Skipped: Amethystora's own files, which overlay the upstream ones in /ctx under their own names
# (amethystora-*) and, for the spinner theme, under Fedora's name for the watermark.
for file in /ctx/system_files/shared/usr/share/pixmaps/* \
    /ctx/system_files/shared/usr/share/icons/hicolor/scalable/places/* \
    /ctx/system_files/shared/usr/share/plymouth/themes/spinner/*; do
    name="$(basename "${file}")"
    target="${file#/ctx/system_files/shared}"
    if [[ ! -f "${file}" ]] || [[ "${name}" == amethystora-* ]] ||
        [[ "${name}" == watermark.png ]] ||
        grep -qiE "ublue|bluefin|universal.?blue" <<<"${name}"; then
        continue
    fi
    if [[ -z "${UPSTREAM_ARTWORK[${target}]:-}" ]]; then
        echo "::error::${target} is upstream artwork with no Amethystora replacement"
        exit 1
    fi
done

# Top bar: the Logo Menu draws the Amethystora gem in its own colours, not a symbolic silhouette
# that GNOME would repaint in the panel's foreground white. Upstream sets symbolic-icon=true and
# menu-button-icon-image=30, which is entry 31 of the symbolic list; Amethystora turns the symbolic
# icon off and moves the index to 29, entry 30 of the coloured list. Both entries are upstream's
# Universal Blue logo, and both are replaced with Amethystora artwork below, under the upstream file
# names that 07-debrand.sh then renames. Selecting the entries by number is what makes the checks
# necessary: a reordered list would silently put somebody else's logo in the panel.
LOGOMENU=/usr/share/gnome-shell/extensions/logomenu@aryan_k
logomenu_entries() {
    sed -n "/$1/,/^\];/p" "${LOGOMENU}/constants.js" | grep -oE "/Resources/[^']+"
}
# menu-button-icon-image indexes the arrays from 0, and the symbolic array opens with a plain icon
# name carrying no /Resources/ path: index 30 is the 30th path listed there, index 29 the 30th here.
[[ "$(logomenu_entries SymbolicDistroIcons | sed -n '30p')" == "/Resources/ublue-logo-symbolic.svg" ]]
install -Dpm0644 /usr/share/icons/hicolor/scalable/actions/amethystora-logo-symbolic.svg \
    "${LOGOMENU}/Resources/ublue-logo-symbolic.svg"
[[ "$(logomenu_entries ColouredDistroIcons | sed -n '30p')" == "/Resources/ublue-logo.svg" ]]
install -Dpm0644 /usr/share/icons/hicolor/scalable/apps/amethystora-logo.svg \
    "${LOGOMENU}/Resources/ublue-logo.svg"

# The extension keeps its settings in dconf, not in a gschema override, so the base image's defaults
# are edited in place rather than restated; anything else it sets there keeps coming through.
LOGOMENU_DCONF=/etc/dconf/db/distro.d/04-bluefin-logomenu-extension
if upstream_has "${LOGOMENU_DCONF}"; then
    sed -i \
        -e "s|^symbolic-icon=.*|symbolic-icon=false|" \
        -e "s|^menu-button-icon-image=.*|menu-button-icon-image=29|" \
        "${LOGOMENU_DCONF}"
    grep -q "^symbolic-icon=false$" "${LOGOMENU_DCONF}"
    grep -q "^menu-button-icon-image=29$" "${LOGOMENU_DCONF}"
fi

# ChairLift help page
if upstream_has /usr/share/chairlift/config.yml; then
    sed -i \
        -e "s|^\(\s*website:\).*|\1 ${REPO_URL}#readme|" \
        -e "s|^\(\s*issues:\).*|\1 ${REPO_URL}/issues|" \
        -e "s|^\(\s*chat:\).*|\1 ${REPO_URL}/discussions|" \
        /usr/share/chairlift/config.yml
fi

# `ujust report` and `ujust changelogs` resolve the GitHub repo from the image name;
# amethystora matches no upstream name, so they use these defaults.
# The report title swaps the blueberry emoji for a purple heart, matched as UTF-8 bytes.
EMOJI_SWAP='s/\xf0\x9f\xab\x90 Bluefin/\xf0\x9f\x92\x9c Amethystora/g'
if upstream_has /usr/share/ublue-os/just/60-bonedigger.just; then
    LC_ALL=C sed -i "${EMOJI_SWAP}" /usr/share/ublue-os/just/60-bonedigger.just
fi
if upstream_has /usr/libexec/bonedigger-report; then
    LC_ALL=C sed -i "${EMOJI_SWAP}" /usr/libexec/bonedigger-report
    sed -i \
        -e "s|--default \"projectbluefin/common\"|--default \"${REPO}\"|" \
        -e "s|create_draft \"projectbluefin/common\"|create_draft \"${REPO}\"|" \
        -e "s|https://github.com/projectbluefin/common/issues/new|${REPO_URL}/issues/new|" \
        -e "s|https://github.com/ublue-os/bluefin/discussions|${REPO_URL}/discussions|" \
        -e 's/Bluefin Discussions/Amethystora Discussions/' \
        /usr/libexec/bonedigger-report
fi
if upstream_has /usr/share/ublue-os/just/changelog.just; then
    sed -i "s|--default \"projectbluefin/bluefin\"|--default \"${REPO}\"|" /usr/share/ublue-os/just/changelog.just
fi

echo "::endgroup::"
